function leave(){if(!ui.pending.value)return true;ui.notice.value='原请求结果待核对，请先在本页恢复。';return false}onBeforeRouteLeave(leave);onBeforeRouteUpdate(leave)
function unload(e:BeforeUnloadEvent){if(!leave()){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{window.addEventListener('beforeunload',unload);timer.value=window.setInterval(()=>now.value=Date.now(),1000);try{await Promise.all([session.loadAccount(),session.loadParties()])}catch(e){ui.error.value=asApiError(e)}finally{loading.value=false;reset();if(typeof route.query.action==='string')operationKey.value=route.query.action;await load()}})
onUnmounted(()=>{window.removeEventListener('beforeunload',unload);window.clearInterval(timer.value)})
</script>
<template><div class="supply-workspace editorial-workspace business-workspace" :data-gallery="`WEB-V5-${domain.key}`"><header class="supply-header"><RouterLink to="/workspace" class="supply-brand">晶晶日上</RouterLink><span>先锋电影刊物 · {{domain.title}}</span><div class="account-actions"><span class="account-name">{{session.account?.display_name||'当前账号'}}</span><button @click="session.logout().then(()=>router.push('/login'))">退出</button></div></header><div class="supply-layout"><aside class="supply-sidebar"><button class="outline editorial-menu-toggle" :aria-expanded="menu" aria-controls="business-menu" @click="menu=!menu">工作区导航 <span>{{menu?'收起':'展开'}}</span></button><div id="business-menu" class="editorial-menu" :class="{expanded:menu}"><WorkspaceNav/><div class="supply-identity"><label for="business-party">当前办理身份</label><select id="business-party" :value="session.selectedId" :disabled="locked" @change="session.selectParty(($event.target as HTMLSelectElement).value)"><option v-for="p in session.parties" :key="p.party.id" :value="p.party.id">{{p.party.display_name}}</option></select><p v-if="section.party==='none'">本栏按当前账号权限读取；独立审核以岗位与回避关系核对。</p><button v-if="session.nextCursor" class="outline" :disabled="locked" @click="session.loadMoreParties">更多办理身份</button></div></div></aside><main class="supply-main"><div class="supply-heading"><div><p class="eyebrow">{{domain.journal}}</p><h1>{{domain.title}}</h1><p>{{domain.intro}}</p></div><button class="outline" :disabled="locked" @click="load">刷新当前记录</button></div><nav class="loaded-tabs" aria-label="本业务办理事项"><RouterLink v-for="s in domain.sections" :key="s.key" :to="`/${domain.key}/${s.key}`" :class="{active:section.key===s.key}">{{s.label}}</RouterLink></nav>
<ApiErrorAlert :error="ui.error.value"/><p v-if="referenceNotice" class="supply-notice" role="status">{{referenceNotice}}</p><p v-if="ui.notice.value" class="supply-notice" role="status">{{ui.notice.value}}</p><section v-if="ui.pending.value" class="supply-warning"><h2>原请求结果待核对</h2><p>{{ui.pending.value.label}}：保留原内容和原版本，先核对同一记录。</p><button :disabled="ui.busy.value" class="outline" @click="checkPending">核对原记录</button><button :disabled="ui.busy.value||!ui.pending.value.checked" class="primary" @click="recover">恢复同一次请求</button></section><label v-if="ui.conflict.value" class="supply-warning trade-check"><input v-model="ui.confirmed.value" type="checkbox">已刷新并核对最新记录，保留输入重新确认本次办理。</label>
<p v-if="domain.note" class="business-intro">{{domain.note}}</p><p v-if="section.note" class="supply-warning">{{section.note}}</p><section v-if="!route.params.recordId&&section.query?.length||referenceFields.length" class="supply-card business-lookup"><h2>{{section.label}}</h2><form class="business-form" @submit.prevent="load"><BusinessFields v-if="section.query?.length&&!route.params.recordId" v-model="filters" :fields="section.query" :disabled="locked" prefix="filter"/><BusinessFields v-if="referenceFields.length" v-model="reference" :fields="referenceFields" :disabled="locked" prefix="reference" :references="refOptions" :reference-busy="refBusy" @read-reference="loadChoices" @reference-selected="selectedReference"/><div class="supply-actions"><button class="outline" :disabled="locked" type="submit">读取当前列表</button><button v-if="section.detail&&!route.params.recordId" class="outline" :disabled="locked" type="button" @click="readReference">读取原记录</button></div></form></section>
<p v-if="loading||ui.busy.value" class="supply-empty" role="status">正在读取或核对当前获准内容……</p><section v-if="rows.length" class="supply-card"><div class="section-heading"><h2>{{section.label}}</h2><span class="business-muted">本页 {{rows.length}} 项</span></div><div class="business-records"><article v-for="(r,i) in rows" :key="recordId(r)||i"><div><p class="eyebrow">{{String(i+1).padStart(2,'0')}}</p><h3>{{title(r)}}</h3><p v-if="typeof rowData(r).body==='string'" class="long-text">{{rowData(r).body}}</p><p v-if="r.current_status||r.effective_status||r.order_status||rowData(r).status"><StateValue :code="String(r.current_status||r.effective_status||r.order_status||rowData(r).status||'')" :label="display(r.current_status||r.effective_status||r.order_status||rowData(r).status||'')"/></p><p class="identifier">{{recordId(r)}}</p></div><button v-if="!String(r.kind).includes('MESSAGE')" class="outline" :disabled="locked" @click="choose(r)">查看与办理</button></article></div><button v-if="ui.data.value?.next_cursor" class="outline" :disabled="locked" @click="cursor=String(ui.data.value.next_cursor);load()">读取下一页</button></section><p v-else-if="hasList&&!ui.busy.value" class="supply-empty">当前没有获准展示的记录。</p>
<section v-if="details" class="supply-card business-current"><div class="section-heading"><h2>{{title(details)}}</h2><span v-if="currentVersion!==null" class="supply-badge">已读取版本 {{currentVersion}}</span></div><p v-if="details.current_status||details.effective_status||details.order_status||rowData(details).status" class="supply-badge"><StateValue :code="String(details.current_status||details.effective_status||details.order_status||rowData(details).status||'')" :label="display(details.current_status||details.effective_status||details.order_status||rowData(details).status||'')"/></p><BusinessOverview :record="details" :domain="domain.key"/><details class="business-source"><summary>核对原约定、权利与办理记录</summary><BusinessDetails :value="details" :field-labels="fieldLabels"/></details><div class="supply-actions"><RouterLink v-if="uuid(details.order_id)||details.kind==='ORDER'&&uuid(details.id)" :to="`/trade/orders/${details.order_id||details.id}`" class="button-link outline">原订单与合同</RouterLink><RouterLink v-if="uuid(details.order_id)||details.kind==='ORDER'&&uuid(details.id)" :to="`/trade/payments/new?orderId=${details.order_id||details.id}`" class="button-link outline">按原订单办理付款</RouterLink><RouterLink v-if="domain.key==='participation'&&uuid(reference.project_id)" :to="`/projects/projects/${reference.project_id}`" class="button-link outline">原出品项目与发行</RouterLink><RouterLink v-if="domain.key==='participation'" to="/finance/agreements" class="button-link outline">收入对账与到账</RouterLink><RouterLink v-if="uuid(rowData(details).quote_id)" :to="`/trade/quotes/${rowData(details).quote_id}`" class="button-link outline">读取正式报价</RouterLink></div></section>
<section v-if="section.files?.length&&(details||domain.key==='conversations'&&rows.length)" class="supply-card"><h2>获准查看的文件</h2><label v-if="section.files.some(f=>/:asset_id|:message_id/.test(f.path))" for="business-asset">本记录列明的私有材料<select id="business-asset" v-model="assetId" :disabled="locked"><option value="">请选择本次实际材料</option><option v-for="id in attachmentIds" :key="id" :value="id">本次材料 · {{id.slice(0,8)}}</option></select></label><div class="supply-actions"><button v-for="f in section.files" :key="f.path" class="outline" :disabled="locked" @click="openFile(f)">{{f.label}}</button></div><video v-if="fileUrl&&fileType==='video/mp4'" :src="fileUrl" controls playsinline preload="metadata" @playing="filePlayed=true" @error="filePlayed=false;ui.notice.value='文件未能播放，尚未完成查看。'"/><img v-else-if="fileUrl&&fileType.startsWith('image/')" :src="fileUrl" alt="本次获准查看的实际私有材料" class="business-private-image" @load="filePlayed=true" @error="filePlayed=false"/><audio v-else-if="fileUrl&&fileType.startsWith('audio/')" :src="fileUrl" controls @playing="filePlayed=true" @error="filePlayed=false"/><p v-else-if="fileText" class="business-private-text">{{fileText}}</p><a v-else-if="fileUrl" :href="fileUrl" download="获准的私有材料" class="button-link outline">保存已取得的私有文件</a><button v-if="domain.key==='stock'&&section.key==='purchases'" :disabled="locked||!filePlayed" class="outline" @click="readNotification">读取本次交付通知</button><p v-if="fileUrl" class="business-muted">文件仅在本次获准会话中保留，切换身份或离开后清除。</p></section>
<section v-if="actions.length" class="supply-card"><h2>办理下一步</h2><div class="business-actions"><button v-for="a in actions" :key="a.key" :class="operationKey===a.key?'primary selected':'outline'" :aria-pressed="operationKey===a.key" :disabled="locked" @click="operationKey=a.key">{{a.label}}</button></div><form v-if="action" class="business-form" @submit.prevent="submit"><h3>{{action.label}}</h3><p v-if="action.party==='none'" class="supply-warning">此操作以独立岗位身份提交，服务器核对实际权限及回避关系。</p><p v-if="action.note">{{action.note}}</p><BusinessFields v-model="draft" :fields="actionFields" :disabled="locked" :prefix="action.key" :references="refOptions" :reference-busy="refBusy" @read-reference="loadChoices" @reference-selected="selectedReference"/><label class="trade-check"><input v-model="agreed" type="checkbox" :disabled="locked">已阅读当前记录与本次约定，明确提交上述办理事项。</label><button type="submit" class="primary" :disabled="locked||!agreed||action.match&&currentVersion===null" :data-testid="`business-${action.key}`">{{action.label}}</button></form></section>
<details v-if="materialPreparation" class="supply-card business-upload"><summary>准备本次私有材料</summary><p>上传成功后，可在本次表单选择刚上传的实际材料。权利文件、取样及其他用途须与原授权一致。</p><label for="business-purpose">材料用途</label><select id="business-purpose" v-model="uploadPurpose" :disabled="locked"><option value="RIGHTS_EVIDENCE">权利依据</option><option value="REVIEW_EVIDENCE">复核依据</option><option value="CONSENT_EVIDENCE">本人同意依据</option><option value="AVATAR_MATERIAL">本人数字人原始素材</option><option value="WORK_CONTENT">作品内容</option><option v-if="domain.key==='cocreation'&&uuid(reference.project_id)" value="PRODUCTION_FILE">本原制作项目的本人片段MP4（50MiB内）</option><option v-if="domain.key==='stock'" value="STOCK_VIDEO">现货预览或正式MP4（50MiB内）</option></select><label for="business-upload-file">选择本地文件</label><input id="business-upload-file" type="file" :disabled="locked" @change="uploadFile=($event.target as HTMLInputElement).files?.[0]||null"><button class="outline" :disabled="locked||!uploadFile" @click="upload">上传私有材料</button><BusinessDetails v-if="uploaded" :value="uploaded"/></details>
</main></div></div></template>
